package ec.edu.uagraria.prog3; import static org.junit.jupiter.api.Assertions.assertEquals;import static org.junit.jupiter.api.Assertions.assertFalse;import static org.junit.jupiter.api.Assertions.assertNotEquals;import static org.junit.jupiter.api.Assertions.assertTrue; import ec.edu.uagraria.prog3.dominio.Cacao;import ec.edu.uagraria.prog3.fabrica.DatosProducto;import ec.edu.uagraria.prog3.fabrica.FabricaProductos;import ec.edu.uagraria.prog3.fabrica.TipoProducto;import org.junit.jupiter.api.Test; class CacaoTest {     private static Cacao cacao(String variedad, boolean organico) {        return (Cacao) FabricaProductos.crear(                TipoProducto.CACAO, DatosProducto.deCacao(variedad, organico));    }     @Test    void guardaVariedadYOrganico() {        Cacao cacao = cacao("Nacional", true);         assertEquals("Nacional", cacao.variedad());        assertTrue(cacao.organico());    }     @Test    void nombreComunEsCacaoMasVariedad() {        assertEquals("Cacao Nacional", cacao("Nacional", false).nombreComun());    }     @Test    void cacaoNoOrganicoSeReportaComoTal() {        assertFalse(cacao("CCN-51", false).organico());    }     @Test    void igualdadConsideraTodosLosCampos() {        assertEquals(cacao("Nacional", true), cacao("Nacional", true));        assertNotEquals(cacao("Nacional", true), cacao("Nacional", false));    }}